function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'MyCircularDeque' || args[0].length !== 1) return 'Start with MyCircularDeque and its capacity k.';
  const k = args[0][0];
  if (!Number.isInteger(k) || k < 1 || k > 1000) return 'k is a whole number from 1 to 1000.';
  if (operations.length - 1 > 2000) return 'At most 2000 calls after the constructor.';
  const takesValue = new Set(['insertFront', 'insertLast']);
  const noArgs = new Set(['deleteFront', 'deleteLast', 'getFront', 'getRear', 'isEmpty', 'isFull']);
  for (let i = 1; i < operations.length; i++) {
    const name = operations[i];
    if (takesValue.has(name)) {
      if (args[i].length !== 1) return `${name} takes one value.`;
      const value = args[i][0];
      if (!Number.isInteger(value) || value < 0 || value > 1000) return 'Each value is a whole number from 0 to 1000.';
    } else if (noArgs.has(name)) {
      if (args[i].length !== 0) return `${name} takes no arguments.`;
    } else {
      return `Unknown operation ${name}.`;
    }
  }
  return null;
}

