class MyCircularDeque {
  // A growable JavaScript array with a size check; unshift and shift cost O(n) but are obviously right.
  constructor(k) {
    this.k = k;
    this.list = [];
  }
  insertFront(value) {
    if (this.list.length === this.k) return false;
    this.list.unshift(value);
    return true;
  }
  insertLast(value) {
    if (this.list.length === this.k) return false;
    this.list.push(value);
    return true;
  }
  deleteFront() {
    if (this.list.length === 0) return false;
    this.list.shift();
    return true;
  }
  deleteLast() {
    if (this.list.length === 0) return false;
    this.list.pop();
    return true;
  }
  getFront() { return this.list.length ? this.list[0] : -1; }
  getRear() { return this.list.length ? this.list[this.list.length - 1] : -1; }
  isEmpty() { return this.list.length === 0; }
  isFull() { return this.list.length === this.k; }
}

