function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const k = large ? (rand() < 0.5 ? 1 + pick(20) : 1 + pick(1000)) : 1 + pick(4);
  const calls = large ? 499 : 1 + pick(15);
  const maxValue = large || rand() < 0.5 ? 1000 : 9;
  // Lean towards inserts or deletes in phases so the deque both fills up and drains.
  let insertBias = 0.5;
  const operations = ['MyCircularDeque'];
  const args = [[k]];
  for (let i = 0; i < calls; i++) {
    if (rand() < 0.08) insertBias = 0.2 + rand() * 0.6;
    const roll = rand();
    if (roll < 0.6) {
      const insert = rand() < insertBias;
      const front = rand() < 0.5;
      operations.push(insert ? (front ? 'insertFront' : 'insertLast') : (front ? 'deleteFront' : 'deleteLast'));
      args.push(insert ? [pick(maxValue + 1)] : []);
    } else {
      operations.push(['getFront', 'getRear', 'isEmpty', 'isFull'][pick(4)]);
      args.push([]);
    }
  }
  return [operations, args];
}
